SELECT a.id, a.user_id, a.schedule_id, a.status
FROM appointment a
JOIN schedule s ON s.id = a.schedule_id
WHERE a.id = #{appointmentId}
  AND s.doctor_id = #{doctorId}
FOR UPDATE

SELECT id, name, spec, unit, price, stock, usage_desc, status, create_time, update_time FROM medicine WHERE id IN
#{medicineId}
ORDER BY id ASC FOR UPDATE

mapper.update:
UPDATE consultation_record
SET chief_complaint = #{chiefComplaint},
    present_illness = #{presentIllness},
    diagnosis = #{diagnosis},
    treatment_plan = #{treatmentPlan},
    doctor_advice = #{medicalAdvice},
    update_time = NOW()
WHERE id = #{id}
  AND appointment_id = #{appointmentId}
  AND doctor_id = #{doctorId}

UPDATE medicine
SET stock = stock - #{quantity},
    update_time = NOW()
WHERE id = #{medicineId}
  AND status = 1
  AND stock >= #{quantity}

UPDATE prescription
SET status = 'dispensed',
    update_time = NOW()
WHERE id = #{prescriptionId}
  AND appointment_id = #{appointmentId}
  AND user_id = #{userId}
  AND doctor_id = #{doctorId}
  AND status = 'paid'

